from estimar_robustez import *
def textjson(x):return json.dumps(clean(x),ensure_ascii=False,sort_keys=True)
def expr(t,s):
    if ' × ' in t:
        a,b=t.split(' × ');return '('+expr(a,s)+') × ('+expr(b,s)+')'
    lag=s.get('lags',{}).get(t,0);tr=s.get('transforms',{}).get(t,'level');a=f'L{lag}_calendario({t})' if lag else t
    return f'ln({a})' if tr=='log' else f'ln(1+{a})' if tr=='log1p' else a
def main():
    rr=json.loads((HERE/'resultados_robustez.json').read_text(encoding='utf8'));byid={r['id']:r for r in rr}
    meta=json.loads((HERE/'metadata_robustez.json').read_text(encoding='utf8'));plan=meta['plan'];full,cat,_=load_data()
    summary=[['Candidata','Variável dependente','N comum','Coeficiente da interação','p cluster município','p cluster município + ano','Avaliação de robustez','EP cluster município','EP cluster município + ano','IC 95% duas dimensões inferior','IC 95% duas dimensões superior','Municípios','Anos','GL t duas dimensões','Base sem interação','R2 parcial aos FE: base','R2 parcial aos FE: interação','Δ R2 parcial aos FE','R2 total com interação','Razão EP duas dimensões / municipal','ID amostra','Limites de inferência']]
    models=[['ID do ajuste','Modelo original','Variável dependente','Especificação','Covariância','N comum','Municípios','Anos','GL inferência t','R2 total','R2 ajustado','R2 parcial aos FE','Parâmetros totais','GL residuais','ID amostra','Termos econômicos mantidos','Termos absorvidos','Fórmula efetiva','Filtros e preparação','Exclusões até amostra comum','Interação tem inferência marginal calculável?','Advertências do dashboard']]
    coeff=[['ID do ajuste','Candidata','Variável dependente','Covariância','Termo técnico','Expressão efetiva','Tipo de termo','Coeficiente','Erro-padrão','Estatística t','Valor-p','IC 95% inferior','IC 95% superior','Variância estimada','Situação da inferência']]
    diag=[['ID do ajuste','Covariância','N','Clusters municipais','Clusters anuais (calendário observado)','GL t','Diagonais negativas na matriz completa','Termos com variância negativa','Diagonais econômicas negativas','Menor autovalor da covariância completa','Menor autovalor do bloco econômico padronizado','Bloco econômico PSD (tol 1e−8)','Interação: variância positiva','Erro absoluto máximo: covariância independente','Erro absoluto máximo: slopes FWL','Municípios com uma observação','Amostra comum SHA256','Validação e limite']]
    absorption=[['Candidata / base','Variável dependente','Termo original','Expressão efetiva','Situação','Norma residual / original','Regra econômica / identificação']]
    methods=[['Categoria','Item','Conteúdo','Origem']]
    def note(a,b,c,d='Execução local; rotina h1lab/models.py'):methods.append([a,b,str(c),d])
    for mid in FOCUS:
        mun=byid[mid+'_MUN'];two=byid[mid+'_MUN_ANO'];base=byid[BASE[mid]+'_MUN_ANO']
        c=next(v for v in two['coef'] if ' × ' in v['term']);u=next(v for v in mun['coef'] if v['term']==c['term'])
        assert c['coef']==u['coef']
        s=two['summary'];label=pretty(two['y'])
        interpretation=('Sinal negativo preservado; evidência não se mantém a 5% com cluster em duas dimensões (p≈0,097). IC95% inclui zero; resultado apenas marginal a 10%, exploratório.' if mid in ['M042','M142'] else 'Sinal positivo preservado, mas significância a 5% do cluster municipal desaparece (p≈0,151). IC95% inclui zero.' if mid=='M092' else 'Interação permanece imprecisa (p≈0,886). Nenhuma evidência de diferença da associação ao preço por aptidão nesta especificação.')
        limit='Só 23 clusters anuais, t com 22 GL; aproximação assintótica frágil. Bloco econômico tem variâncias positivas e é PSD na tolerância; matriz completa tem diagonais negativas em algumas dummies, cujos EP/testes/IC são indisponíveis. Sem correção PSD, bootstrap ou ajuste por seleção de especificações.'
        summary.append([mid,label,s['N'],c['coef'],u['p'],c['p'],interpretation,u['se'],c['se'],c['ci_low'],c['ci_high'],s['Municípios'],s['Anos'],s['Graus de liberdade da inferência'],BASE[mid],base['summary']['R2 parcial aos efeitos fixos'],s['R2 parcial aos efeitos fixos'],s['R2 parcial aos efeitos fixos']-base['summary']['R2 parcial aos efeitos fixos'],s['R2'],c['se']/u['se'],two['sample_id'],limit])
        note('Conclusão',mid,interpretation+f' b={c["coef"]:.10g}; EP municipal={u["se"]:.10g}; EP município+ano={c["se"]:.10g}; p duas dimensões={c["p"]:.10g}.')
    for r in rr:
        s=r['summary'];mid=r['candidate'];spec=r['original_spec'];cov=r['fit_spec']['cov'];label=pretty(r['y'])
        covlabel='Município + ano' if cov=='cluster_twoway' else 'Município'
        interaction=next((c for c in r['coef'] if ' × ' in c['term']),None)
        marginal=interaction['variance']>0 and interaction['se'] is not None if interaction else None
        formula=r['y']+' = α_i + λ_t + '+' + '.join(expr(t,spec) for t in r['kept'])+' + ε_it'
        models.append([r['id'],mid,label,'Preço × aptidão' if mid in FOCUS else 'Base sem interação',covlabel,s['N'],s['Municípios'],s['Anos'],s['Graus de liberdade da inferência'],s['R2'],s['R2 ajustado'],s['R2 parcial aos efeitos fixos'],r['parameters'],s['Graus de liberdade residuais'],r['sample_id'],'; '.join(r['kept']),'; '.join(r['absorbed']),formula,textjson({'filters':FILTERS,'original_spec':spec,'fit_spec':r['fit_spec']}),textjson({'original_N':r['original_sample_N'],'common_N':s['N'],'ledger':r['ledger'],'missing':r['missing']}),marginal,' '.join(r['warnings'])])
        bad=[c['term'] for c in r['all_coef'] if c['variance']<0]
        diag.append([r['id'],covlabel,s['N'],s['Municípios'],s['Anos'],s['Graus de liberdade da inferência'],r['covariance_negative_diagonal_full'],'; '.join(bad),'; '.join(r['covariance_negative_diagonal_economic']),r['covariance_min_eigenvalue_full'],r['covariance_min_eigenvalue_scaled_economic'],r['covariance_economic_psd_tol1e8'],marginal,r['independent_covariance_max_abs_error'],r['fwl_slopes_max_abs_error'],r['singleton_municipalities'],r['sample_id'],'Matriz completa e bloco econômico avaliados separadamente. Nenhum teste conjunto que use a matriz completa é apresentado. Estatísticas marginais apenas para termos com variância positiva e EP finito.'])
        for c in r['all_coef']:
            term=c['term'];kind='Dummy FE' if term.startswith('FE_') else 'Intercepto / categoria-base' if term=='const' else 'Regressor econômico'
            effective=expr(term,spec) if kind=='Regressor econômico' else 'Dummy aditiva / normalização'
            status=c['inference_status']
            if cov=='cluster_twoway' and kind=='Regressor econômico':status+=' Bloco econômico PSD; 23 clusters anuais, t22; ressalva de poucos clusters e da matriz global indefinida.'
            coeff.append([r['id'],mid,label,covlabel,term,effective,kind,c['coef'],c['se'],c['t'],c['p'],c['ci_low'],c['ci_high'],c['variance'],status])
        if cov=='cluster_twoway':
            for term,ratio in r['absorption_ratios'].items():
                absorbed=term in r['absorbed']
                why=('Série comum por ano: absorvida por FE anuais.' if 'preco' in term and ' × ' not in term else 'Atributo fixo por município: absorvido por FE municipais.') if absorbed else 'Variação residual após FE de município e ano. Produtos mantidos mesmo quando constituintes são absorvidos.'
                absorption.append([mid,label,term,expr(term,spec),'Absorvido — coeficiente não identificado' if absorbed else 'Mantido',ratio,why])
                if absorbed:coeff.append([r['id'],mid,label,covlabel,term,expr(term,spec),'Regressor absorvido',None,None,None,None,None,None,None,'Não identificado; não equivale a coeficiente zero. '+why])
    note('Escopo','Robustez executada','Quatro interações das candidatas M042/M092/M142/M192 e quatro bases sem interação M022/M072/M122/M172. 8 especificações TWFE × 2 covariâncias = 16 ajustes. Sem nova proxy, transformação, seleção por p, bootstrap, remoção de extremos ou alterações na tese/dashboard.')
    note('Conclusão','Evidência a 5%','Nenhuma das quatro interações tem IC95% que exclua zero sob agrupamento por município e ano. Sinais e coeficientes pontuais são idênticos aos do agrupamento municipal. A robustez da significância a 5% não se sustenta; isso não demonstra efeito exatamente nulo ou rejeição geral de H1.')
    note('Amostra','Interseção',f'Interseção exata de codigo_ibge,ano após casos completos das 8 especificações originais: N={plan["common_N"]}; 137 municípios; 23 anos, 2002–2024. Hash={plan["common_sample_sha256"]}. Não houve perda adicional em relação às quatro candidatas anteriores; cada uma já usava essa amostra.')
    note('Amostra','Preservação do timing','Construção por prepare_sample no painel completo. Para restringir à interseção, mantém-se o painel integral e mascara-se apenas Y fora da interseção antes de preparar a amostra. Assim a defasagem de chuva por ano civil exato preserva o ano antecedente. As transformações e os produtos originais são aplicados uma só vez.')
    note('Amostra','Filtros e ausências','2001–2024 solicitado, todos os municípios e Amazônia/Cerrado/Pantanal; require_y=True. Cobertura completa de Y, dados finitos, casos completos para cada especificação original. Sem imputar zero, winsorizar, balancear painel ou excluir outliers. 2001 sem lag de chuva; período efetivo 2002–2024. Três municípios com apenas um par são mantidos; não contribuem variação própria às inclinações within, e podem gerar influência clássica indefinida.')
    note('FE e absorção','Configuração','Dummies explícitas de município e ano e intercepto com categoria-base, usando h1lab.models.fit_model, fe=twoway. Preço próprio (ln real t−1) é comum por ano; GAEZ z e ln área de referência de 2000 são fixos municipais: três termos absorvidos por especificação. Interação preço × GAEZ permanece identificável; efeitos principais estão no espaço das dummies, não são efeitos iguais a zero.')
    note('Covariância','Agrupamento em duas dimensões','cov=cluster_twoway: inclusão-exclusão V_município + V_ano − V_par_município_ano. A chave do painel é única; a última parcela usa grupos de observações individuais. Cada componente tem correção G/(G−1) × (N−1)/(N−K), com K incluindo todos os parâmetros independentes, inclusive FE. Não é agrupar somente pelo par município-ano.')
    note('Covariância','Graus de liberdade','use_correction=True, df_correction=True, use_t=True. Municipal: 137 clusters, t136. Município+ano: 137 e 23 clusters, t com min(137,23)−1=22 GL. p bilateral e IC95% obtidos do mesmo ajuste completo. A mudança de covariância e de GL altera a inferência, sem alterar coeficientes, N ou R2.')
    note('Covariância','Matriz indefinida','A matriz completa de duas dimensões apresenta diagonais negativas em algumas dummies FE. Seus EP, testes e IC são registrados como indisponíveis (células vazias com motivo); coeficientes pontuais preservados. Não truncar variâncias em zero, tomar valor absoluto ou projetar para PSD. A aba Diagnósticos discrimina o bloco econômico: variâncias positivas e matriz PSD na tolerância para os ajustes deste lote. Estatísticas marginais dessas interações são calculáveis, com ressalvas; não é validação da matriz completa ou autorização de testes conjuntos gerais.')
    note('Inferência','Poucos clusters e limites','Somente 23 clusters anuais; aproximações assintóticas em duas dimensões podem ser frágeis, mesmo com correção finita e t22. Esta etapa não aplicou bootstrap, correção de múltiplos testes ou estimação alternativa para poucos clusters. Interações herdadas da exploração de 200 modelos: p-valores não incorporam essa seleção. FE e cluster não garantem causalidade nem resolvem tendências territoriais, endogeneidade e mensuração.')
    note('Inferência','Escala econômica','Hectares preservados. Taxas em fração (multiplicar coeficientes por 100 para pontos percentuais). Produto de ln(preço real defasado) com aptidão GAEZ em z original. Coeficiente é diferença da associação ao preço por 1 DP de aptidão, condicional aos controles e FE. Não há coeficiente comum do preço identificado sob efeitos anuais. GAEZ milho na pastagem representa oportunidade agrícola/alimentação, não aptidão pecuária direta.')
    note('Ajuste','Comparações','Bases e interações usam rigorosamente a mesma amostra global. R2 total inclui dummies; R2 parcial aos FE = 1−SSE_com_X/SSE_apenas_FE. ΔR2 parcial é diferença desses R2 em modelos aninhados na mesma dependente e amostra. Comparação municipal versus duas dimensões não muda o ajuste e não é um novo teste de mecanismo econômico.')
    note('Validação','Covariância independente','Reconstruída numericamente via pseudoinversa da matriz X completa, soma de escores de grupos e inclusão-exclusão das três parcelas com as mesmas correções finitas; comparada à matriz inteira retornada por statsmodels. Slopes também conferidos independentemente por FWL. Inferência vem sempre do modelo completo; nenhum EP iid dos resíduos FWL foi utilizado.')
    note('Validação','Estabilidade e integridade','Coeficientes e R2 idênticos nas duas covariâncias. Slopes reproduzem os TWFE anteriores porque a amostra não mudou. Posto completo, GL residuais positivos e chaves da amostra validados. Zero falhas de estimação; limitações das covariâncias e dos diagnósticos clássicos explicitadas, sem ocultação. Reabertura do Excel e conferência de todas as células, IDs, amostras e preservação por SHA256 no script verificar_excel.py.')
    note('Rastreabilidade','Data/ambiente',meta['date']+'; Python='+meta['python_executable']+'; numpy='+meta['numpy']+'; pandas='+meta['pandas']+'; statsmodels='+meta['statsmodels']+'; main, HEAD='+meta['git_head']+'. Estado inicial limpo; sem branch/worktree, commit ou push.')
    note('Rastreabilidade','Fonte CSV',str(CSV)+'; SHA256='+meta['data']['csv_sha256'])
    for name,digest in plan['source_xlsx_sha256'].items():note('Preservação','Excel anterior '+name,'SHA256 antes/depois='+digest,str(APP/name))
    for path,digest in plan['code_sha256'].items():note('Preservação','Código '+path,'SHA256='+digest,path)
    note('Fontes','Definições e H1','AGENTS.md; 2_INTI/RESEARCH_PROTOCOL.md; pt_h1/README.md; h1lab/models.py e data.py; dicionário aed_chap1_pt_DICIO.ipynb; introdução H1/REF7–REF8; revisão, Preços, capacidade produtiva e usos alternativos da terra. Angelsen (2010), Berman et al. (2023), Lubowski et al. (2008), Chomitz e Thomas (2003), Bragança (2018), conforme revisão local. Não foi realizada nova auditoria dos artigos originais.')
    for col in sorted(set(t for r in rr for t in [r['y'],*r['original_spec']['xs']])):note('Dicionário / interface',pretty(col),col+'; '+cat.loc[col,'definition']+'; unidade='+cat.loc[col,'unit'],str(DICIO))
    note('Reprodução','Comando completo',f'& "{HERE / "reproduzir_robustez.ps1"}"; estima/retoma os 16 ajustes, consolida, exporta novo Excel e verifica integridade. Usa .venv para regressões e runtime bundled para authoring/leitura do Excel. Resultados anteriores somente leitura.')
    note('Plano','Registro anterior ao ajuste',textjson(plan),'plano_robustez.json')
    common=pd.read_csv(HERE/'amostra_comum.csv',dtype={'codigo_ibge':str})
    for year,g in common.groupby('ano'):note('Chaves da amostra comum',str(year),','.join(sorted(g.codigo_ibge)),'Identificadores textuais, nunca regressores numéricos')
    for name in ['estimar_robustez.py','exportar_excel.mjs','verificar_excel.py','reproduzir_robustez.ps1']:
        if (HERE/name).exists():
            lines=(HERE/name).read_text(encoding='utf8').splitlines()
            for i in range(0,len(lines),10):note('Código de reprodução',f'{name}: {i+1}–{min(i+10,len(lines))}','\n'.join(lines[i:i+10]),name)
    payload={'Robustez':summary,'Modelos':models,'Coeficientes':coeff,'Diagnósticos':diag,'Absorção':absorption,'Metodologia':methods}
    for name,rows in payload.items():assert all(len(r)==len(rows[0]) for r in rows),name
    save('excel_payload.json',payload)
    audit=ROOT/'2_INTI/audit/robustez_interacoes_20261018';audit.mkdir(parents=True,exist_ok=True)
    (audit/'RELATORIO.md').write_text('# Robustez preço × aptidão\n\n16 ajustes TWFE em amostra comum N=2655, G=137, T=23.\n\n'+'\n\n'.join(row[0]+': '+row[6] for row in summary[1:])+'\n\nCovariância independente e FWL conferidos. Diagonais negativas de dummies documentadas; sem reparo PSD. Resultados não causais. Arquivos anteriores preservados por SHA256.\n\nReprodução: '+str(HERE/'reproduzir_robustez.ps1')+'\n\nSem commit/push.\n',encoding='utf8')
    print(f'Excel consolidado: 4 interações, 16 ajustes, {len(coeff)-1} linhas de coeficientes.')
if __name__=='__main__':main()
